-- Document identity is scoped to one hotel. Only the existing authenticated file
-- gateway reaches document bytes; logos are never published in a public bucket.
create table compi_private.document_brand_defaults (
  hotel_key text primary key, accent text not null, logo_png text not null
);
create table compi_private.document_brands (
  hotel_key text primary key, accent text not null check(accent ~ '^[A-F0-9]{6}$'),
  logo_png text check(length(logo_png)<=349528),
  revision integer not null check(revision>0), updated_at timestamptz not null default now()
);
alter table compi_private.document_brand_defaults enable row level security;
alter table compi_private.document_brands enable row level security;
revoke all on compi_private.document_brand_defaults, compi_private.document_brands from public,anon,authenticated;

-- The two factory marks are copied from the original v22 generator templates.
-- BEGIN_FACTORY_MARKS
insert into compi_private.document_brand_defaults values('hotel-arts-barcelona','265973','');
insert into compi_private.document_brand_defaults values('hotel-bruma-del-cobre','833F28','');
-- END_FACTORY_MARKS

create function compi_private.document_brand(h text)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare b compi_private.document_brands; factory compi_private.document_brand_defaults;
begin
  if compi_private.my_rank(h) is null then raise insufficient_privilege;end if;
  select * into b from compi_private.document_brands where hotel_key=h;
  select * into factory from compi_private.document_brand_defaults where hotel_key=h;
  return jsonb_build_object('accent',coalesce(b.accent,factory.accent,'46494A'),
    'logo_png',case when b.revision is not null then b.logo_png else factory.logo_png end,
    'revision',coalesce(b.revision,0),'configured',b.revision is not null);
end $$;

create function public.compi_document_brand(h text) returns jsonb language sql stable security invoker
  set search_path='' as $$ select compi_private.document_brand(h) $$;
create function compi_private.document_brand_revision(h text) returns integer language plpgsql stable security definer
  set search_path='' as $$
begin
  if compi_private.my_rank(h) is null then raise insufficient_privilege;end if;
  return coalesce((select revision from compi_private.document_brands where hotel_key=h),0);
end $$;
create function public.compi_document_brand_revision(h text) returns integer language sql stable security invoker
  set search_path='' as $$ select compi_private.document_brand_revision(h) $$;
revoke all on function compi_private.document_brand(text),public.compi_document_brand(text),
  compi_private.document_brand_revision(text),public.compi_document_brand_revision(text) from public,anon;
grant execute on function compi_private.document_brand(text),public.compi_document_brand(text),
  compi_private.document_brand_revision(text),public.compi_document_brand_revision(text) to authenticated;

-- Edge has already authenticated the caller and decoded/validated the image.
-- Recheck the signed subject, live session, MFA, hotel and rank inside the same
-- transaction as the update; ordinary callers cannot invoke this endpoint.
create function public.compi_commit_document_brand(h text, accent text, logo_png text, expected_revision integer,
  verified_sub uuid, verified_session uuid, verified_aal text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare prior text:=current_setting('request.jwt.claims',true); current_brand jsonb; result jsonb;
begin
  if verified_sub is null or verified_session is null or verified_aal is null or verified_aal not in ('aal1','aal2') then
    raise insufficient_privilege;
  end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',verified_sub,'session_id',verified_session,'aal',verified_aal,'role','authenticated')::text,true);
  perform pg_advisory_xact_lock(hashtextextended(h,731));
  if compi_private.my_rank(h) is distinct from 1 then raise insufficient_privilege;end if;
  if accent is null or accent !~ '^[A-F0-9]{6}$' or expected_revision is null or expected_revision<0 or
      (logo_png is not null and (length(logo_png)>349528 or logo_png not like 'iVBORw0KGgo%')) then
    raise invalid_parameter_value;
  end if;
  current_brand:=compi_private.document_brand(h);
  if (current_brand->>'revision')::integer<>expected_revision then
    if (current_brand->>'accent')=accent and (current_brand->>'logo_png') is not distinct from logo_png then
      perform set_config('request.jwt.claims',coalesce(prior,''),true); return current_brand;
    end if;
    raise exception using errcode='PT409',message='La identidad del hotel ha cambiado.';
  end if;
  if (current_brand->>'accent')=accent and (current_brand->>'logo_png') is not distinct from logo_png then
    result:=current_brand;
  else
    insert into compi_private.document_brands as b (hotel_key,accent,logo_png,revision)
      values(h,accent,logo_png,expected_revision+1)
      on conflict(hotel_key) do update set accent=excluded.accent,logo_png=excluded.logo_png,revision=excluded.revision,updated_at=now();
    result:=compi_private.document_brand(h);
  end if;
  perform set_config('request.jwt.claims',coalesce(prior,''),true);
  return result;
end $$;
revoke all on function public.compi_commit_document_brand(text,text,text,integer,uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.compi_commit_document_brand(text,text,text,integer,uuid,uuid,text) to service_role;
;
